package com.bani.medreminder;
import android.app.*; import android.content.*; import android.os.Build; import java.util.Calendar;
public class AlarmScheduler {
 public static void schedule(Context c,Med m){ AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent i=new Intent(c,AlarmReceiver.class).putExtra("medId",m.id);PendingIntent pi=PendingIntent.getBroadcast(c,(int)m.id,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Calendar cal=Calendar.getInstance();cal.set(Calendar.HOUR_OF_DAY,m.hour);cal.set(Calendar.MINUTE,m.minute);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);if(cal.getTimeInMillis()<=System.currentTimeMillis())cal.add(Calendar.DAY_OF_YEAR,1);long t=cal.getTimeInMillis();if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t,pi);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t,pi); }
 public static void scheduleSnooze(Context c,long medId,long delayMs){ AlarmManager am=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);Intent i=new Intent(c,AlarmReceiver.class).putExtra("medId",medId);PendingIntent pi=PendingIntent.getBroadcast(c,(int)(medId+1000000),i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);long t=System.currentTimeMillis()+delayMs;if(Build.VERSION.SDK_INT>=31&&!am.canScheduleExactAlarms())am.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t,pi);else am.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,t,pi); }
}
